-- Aprenda se Divertindo · 114 · Trilha Policial · lote extra 17 (200 questões fáceis e intermediárias)
-- Rode depois do 113-campeonatos-formatos.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 10547 a 10746: 100 fáceis e 100 intermediárias, com alternativas erradas do mesmo assunto
-- e de tamanho parecido com a certa. Conferidas contra o banco para não repetir.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 10547, "materia": "pen", "nivel": 0, "enunciado": "Pelo Código Penal, a lei penal mais grave que surge depois do crime:", "opcoes": ["Não retroage para prejudicar o réu", "Retroage sempre, para qualquer crime cometido", "Vale só para crimes hediondos", "Retroage se o juiz autorizar"], "explicacao": "A lei penal só retroage para beneficiar o réu (art. 5º, XL, da CF)."}, {"id": 10548, "materia": "pen", "nivel": 0, "enunciado": "A idade a partir da qual a pessoa responde criminalmente pelo Código Penal é:", "opcoes": ["18 anos", "16 anos", "14 anos", "21 anos"], "explicacao": "Menores de 18 anos são penalmente inimputáveis (art. 27 do CP) e seguem o ECA."}, {"id": 10549, "materia": "pen", "nivel": 0, "enunciado": "Quem mata alguém para se defender de um ataque injusto que está acontecendo age em:", "opcoes": ["Legítima defesa", "Estado de necessidade", "Estrito cumprimento do dever legal", "Exercício regular de direito"], "explicacao": "Repelir injusta agressão, atual ou iminente, com meios moderados é legítima defesa (art. 25)."}, {"id": 10550, "materia": "pen", "nivel": 0, "enunciado": "O crime que se consuma quando o agente subtrai, para si, coisa alheia móvel, sem violência, é o:", "opcoes": ["Furto", "Roubo", "Estelionato", "Apropriação indébita"], "explicacao": "Furto é subtrair coisa alheia móvel sem violência ou grave ameaça (art. 155)."}, {"id": 10551, "materia": "pen", "nivel": 0, "enunciado": "Subtrair um celular apontando uma faca para a vítima configura:", "opcoes": ["Roubo", "Furto qualificado", "Extorsão", "Constrangimento ilegal"], "explicacao": "Subtração com grave ameaça ou violência é roubo (art. 157)."}, {"id": 10552, "materia": "pen", "nivel": 0, "enunciado": "Atribuir falsamente a alguém a prática de um crime configura:", "opcoes": ["Calúnia", "Difamação", "Injúria", "Denunciação caluniosa privada"], "explicacao": "Calúnia é imputar falsamente fato definido como crime (art. 138)."}, {"id": 10553, "materia": "pen", "nivel": 0, "enunciado": "Xingar alguém de \"incompetente\", ofendendo sua dignidade, configura:", "opcoes": ["Injúria", "Calúnia", "Difamação", "Ameaça"], "explicacao": "Injúria ofende a dignidade ou o decoro, sem imputar fato (art. 140)."}, {"id": 10554, "materia": "pen", "nivel": 0, "enunciado": "O crime cometido por quem tem a intenção de produzir o resultado é chamado de:", "opcoes": ["Doloso", "Culposo", "Preterdoloso", "Tentado"], "explicacao": "Crime doloso: o agente quis o resultado ou assumiu o risco de produzi-lo (art. 18, I)."}, {"id": 10555, "materia": "pen", "nivel": 0, "enunciado": "Atropelar alguém por dirigir distraído com o celular, sem querer matar, é exemplo de crime:", "opcoes": ["Culposo", "Doloso", "Impossível", "Omissivo próprio"], "explicacao": "Houve imprudência, sem intenção: crime culposo."}, {"id": 10556, "materia": "pen", "nivel": 0, "enunciado": "Um servidor leva para casa o notebook da repartição, que usava no trabalho, e fica com ele de vez. Ele comete:", "opcoes": ["Peculato", "Furto simples", "Apropriação de coisa achada", "Estelionato"], "explicacao": "Apropriar-se de bem que tem a posse em razão do cargo é peculato (art. 312)."}, {"id": 10557, "materia": "pen", "nivel": 0, "enunciado": "Numa blitz, Caio oferece R$ 100 ao agente para seguir viagem. O agente recusa e o prende. Caio cometeu:", "opcoes": ["Corrupção ativa, já consumada com a oferta", "Nenhum crime, pois o agente recusou", "Tentativa de corrupção passiva", "Concussão, por oferecer dinheiro ao policial"], "explicacao": "A corrupção ativa é crime formal: basta oferecer (art. 333)."}, {"id": 10558, "materia": "pen", "nivel": 0, "enunciado": "Prometer a alguém um mal injusto e grave, como dizer que vai matá-lo, configura:", "opcoes": ["Ameaça", "Injúria", "Constrangimento ilegal", "Lesão corporal"], "explicacao": "Ameaça é intimidar alguém com mal injusto e grave (art. 147)."}, {"id": 10559, "materia": "pen", "nivel": 1, "enunciado": "Quem inicia a execução de um crime que não se consuma por circunstâncias alheias à sua vontade responde por:", "opcoes": ["Tentativa, com pena reduzida de 1/3 a 2/3", "Crime consumado, com a mesma pena", "Nenhum crime, por falta de resultado concreto", "Ato preparatório, com pena de multa"], "explicacao": "Art. 14, II e parágrafo único, do CP."}, {"id": 10560, "materia": "pen", "nivel": 1, "enunciado": "Lucas entra numa casa de madrugada, enquanto a família dorme, e leva a TV. Além do furto, incide:", "opcoes": ["Aumento de pena pelo repouso noturno", "O privilégio, por ser réu primário e de bons antecedentes", "A forma culposa do furto", "A extinção da punibilidade"], "explicacao": "Art. 155, § 1º: aumento de um terço."}, {"id": 10561, "materia": "pen", "nivel": 1, "enunciado": "Quem recebe, em proveito próprio, coisa que sabe ser produto de crime comete:", "opcoes": ["Receptação", "Favorecimento real", "Apropriação indébita", "Furto"], "explicacao": "Adquirir ou receber coisa que sabe ser produto de crime é receptação (art. 180)."}, {"id": 10562, "materia": "pen", "nivel": 1, "enunciado": "Em regra, a imputabilidade penal NÃO é excluída pela embriaguez:", "opcoes": ["Voluntária ou culposa", "Completa por caso fortuito", "Completa por força maior", "Patológica que retira o entendimento"], "explicacao": "Embriaguez voluntária ou culposa não exclui a imputabilidade (art. 28, II)."}, {"id": 10563, "materia": "pen", "nivel": 1, "enunciado": "Exigir dinheiro, em razão da função pública, para liberar um alvará configura:", "opcoes": ["Concussão", "Corrupção passiva", "Peculato", "Advocacia administrativa"], "explicacao": "Exigir vantagem indevida em razão da função é concussão (art. 316)."}, {"id": 10564, "materia": "pen", "nivel": 1, "enunciado": "Matar alguém em troca de dinheiro (crime por encomenda) caracteriza homicídio qualificado por:", "opcoes": ["Paga ou promessa de recompensa", "Motivo fútil", "Relevante valor moral", "Emboscada ou dissimulação contra a vítima"], "explicacao": "Art. 121, § 2º, I, do CP."}, {"id": 10565, "materia": "pen", "nivel": 1, "enunciado": "No homicídio culposo, a pena aumenta de um terço se o agente:", "opcoes": ["Deixa de prestar socorro imediato à vítima", "Tinha carteira de motorista válida no momento do fato", "Dirigia durante o dia", "Usava o cinto de segurança"], "explicacao": "Art. 121, § 4º, do CP."}, {"id": 10566, "materia": "pen", "nivel": 1, "enunciado": "Após a Lei 13.718/2018, a ação penal no crime de estupro é:", "opcoes": ["Pública incondicionada", "Privada, mediante queixa", "Pública condicionada à representação", "Privada personalíssima"], "explicacao": "Art. 225 do CP."}, {"id": 10567, "materia": "pen", "nivel": 1, "enunciado": "Quem pratica o fato sob coação moral irresistível:", "opcoes": ["Não é punido; responde o autor da coação", "Responde pelo crime, com pena reduzida pela metade", "Responde junto com o coator", "Responde por crime culposo"], "explicacao": "Art. 22 do CP: só é punível o autor da coação."}, {"id": 10568, "materia": "pen", "nivel": 1, "enunciado": "No regime semiaberto, a pena é cumprida em:", "opcoes": ["Colônia agrícola, industrial ou similar", "Penitenciária de segurança máxima", "Casa do albergado ou prisão domiciliar", "Residência do próprio condenado"], "explicacao": "Art. 33, § 1º, \"b\", do CP."}, {"id": 10569, "materia": "pen", "nivel": 1, "enunciado": "Constranger alguém, mediante violência, a ter conjunção carnal configura:", "opcoes": ["Estupro", "Importunação sexual", "Assédio sexual", "Violação sexual mediante fraude"], "explicacao": "Art. 213 do CP."}, {"id": 10570, "materia": "pen", "nivel": 1, "enunciado": "Avisar a polícia de um crime que sabe não ter acontecido, sem acusar ninguém, configura:", "opcoes": ["Comunicação falsa de crime", "Denunciação caluniosa", "Falso testemunho", "Calúnia"], "explicacao": "Art. 340 do CP. Se acusar alguém, é denunciação caluniosa."}, {"id": 10571, "materia": "ppen", "nivel": 0, "enunciado": "O documento escrito em que a polícia reúne as provas da investigação de um crime é o:", "opcoes": ["Inquérito policial", "Termo circunstanciado", "Processo penal", "Mandado de prisão"], "explicacao": "O inquérito é procedimento administrativo da polícia judiciária."}, {"id": 10572, "materia": "ppen", "nivel": 0, "enunciado": "O Ministério Público pode oferecer denúncia sem inquérito policial quando:", "opcoes": ["Já tiver provas suficientes do crime", "O crime for hediondo ou equiparado a hediondo", "O réu for primário", "A vítima for idosa"], "explicacao": "O inquérito é dispensável (arts. 39, § 5º, e 46, § 1º, do CPP)."}, {"id": 10573, "materia": "ppen", "nivel": 0, "enunciado": "Quem é preso enquanto comete o crime está em flagrante:", "opcoes": ["Próprio", "Impróprio", "Presumido", "Diferido"], "explicacao": "Art. 302, I, do CPP."}, {"id": 10574, "materia": "ppen", "nivel": 0, "enunciado": "Qualquer pessoa do povo, ao ver um crime em andamento:", "opcoes": ["Pode prender o autor em flagrante", "É obrigada a prender o autor", "Só pode chamar a polícia", "Precisa de ordem judicial para agir"], "explicacao": "Art. 301: qualquer do povo pode; a polícia deve prender."}, {"id": 10575, "materia": "ppen", "nivel": 0, "enunciado": "O inquérito policial tem como característica ser:", "opcoes": ["Sigiloso e escrito", "Público e oral", "Contraditório e oral", "Judicial e público"], "explicacao": "Arts. 9º e 20 do CPP."}, {"id": 10576, "materia": "ppen", "nivel": 0, "enunciado": "O delegado, ao concluir a investigação, faz um:", "opcoes": ["Relatório", "Acórdão", "Despacho de pronúncia", "Mandado de citação"], "explicacao": "Art. 10, § 1º, do CPP."}, {"id": 10577, "materia": "ppen", "nivel": 0, "enunciado": "Além da instauração de ofício, o inquérito em crime de ação pública pode começar a requerimento:", "opcoes": ["Do ofendido ou de seu representante", "Somente do juiz, de ofício e sem provocação", "Somente do próprio investigado", "Da imprensa local"], "explicacao": "Art. 5º, II, do CPP."}, {"id": 10578, "materia": "ppen", "nivel": 0, "enunciado": "Nos crimes de ação penal privada, a peça que inicia o processo é a:", "opcoes": ["Queixa-crime", "Denúncia", "Representação", "Portaria"], "explicacao": "A queixa é proposta pelo ofendido ou seu representante."}, {"id": 10579, "materia": "ppen", "nivel": 0, "enunciado": "A prisão decretada pelo juiz durante a investigação de crimes graves, com prazo certo, é a:", "opcoes": ["Prisão temporária", "Prisão em flagrante", "Prisão definitiva", "Prisão civil"], "explicacao": "Lei 7.960/1989."}, {"id": 10580, "materia": "ppen", "nivel": 0, "enunciado": "Em regra, o prazo da prisão temporária em crime comum é de:", "opcoes": ["5 dias, prorrogáveis por mais 5", "10 dias, improrrogáveis", "30 dias, prorrogáveis por mais 30", "48 horas, sem prorrogação"], "explicacao": "Art. 2º da Lei 7.960/1989."}, {"id": 10581, "materia": "ppen", "nivel": 1, "enunciado": "Sabendo de um crime de ação pública incondicionada, o delegado deve instaurar o inquérito:", "opcoes": ["De ofício, por portaria", "Só se a vítima pedir", "Só com ordem do juiz", "Só com autorização do MP"], "explicacao": "Art. 5º, I, do CPP."}, {"id": 10582, "materia": "ppen", "nivel": 1, "enunciado": "Quem tem a qualidade de ser ouvido no inquérito para contar o que sabe sobre o fato, sem ser suspeito, é a:", "opcoes": ["Testemunha", "Vítima", "Investigada", "Perita"], "explicacao": "A testemunha relata fatos de que tem conhecimento."}, {"id": 10583, "materia": "ppen", "nivel": 1, "enunciado": "Entre os fundamentos da prisão preventiva está a garantia:", "opcoes": ["Da ordem pública", "Do pagamento de multa", "Da confissão do réu", "Da punição antecipada"], "explicacao": "Art. 312 do CPP."}, {"id": 10584, "materia": "ppen", "nivel": 1, "enunciado": "O exame de corpo de delito é indispensável nas infrações que:", "opcoes": ["Deixam vestígios", "São de menor potencial ofensivo", "São de ação privada", "Não deixam vestígios"], "explicacao": "Art. 158 do CPP. A confissão não supre sua falta."}, {"id": 10585, "materia": "ppen", "nivel": 1, "enunciado": "A busca domiciliar, quando feita por ordem judicial, deve ocorrer:", "opcoes": ["Durante o dia", "A qualquer hora, inclusive de madrugada", "Somente nos fins de semana", "Apenas com o morador presente e de acordo"], "explicacao": "Art. 5º, XI, da CF e art. 245 do CPP."}, {"id": 10586, "materia": "ppen", "nivel": 1, "enunciado": "Arquivado o inquérito por falta de provas, ele pode ser reaberto se:", "opcoes": ["Surgirem novas provas", "O delegado mudar de opinião", "A vítima pedir, mesmo sem provas", "Passar o prazo de 30 dias"], "explicacao": "Art. 18 do CPP e Súmula 524 do STF."}, {"id": 10587, "materia": "ppen", "nivel": 1, "enunciado": "Na ação penal pública condicionada, sem a representação da vítima:", "opcoes": ["O inquérito nem pode ser iniciado", "O inquérito começa normalmente", "O MP pode denunciar mesmo assim", "O juiz supre a falta de representação"], "explicacao": "Art. 5º, § 4º, do CPP."}, {"id": 10588, "materia": "ppen", "nivel": 1, "enunciado": "A retratação da representação pela vítima, em regra, é possível até:", "opcoes": ["O oferecimento da denúncia", "O recebimento da denúncia", "A sentença de primeiro grau", "O trânsito em julgado"], "explicacao": "Art. 25 do CPP. Na Lei Maria da Penha, só em audiência, antes do recebimento."}, {"id": 10589, "materia": "ppen", "nivel": 1, "enunciado": "Pelo CPP, o reconhecimento de pessoas começa com:", "opcoes": ["A descrição da pessoa a ser reconhecida", "A apresentação de uma só foto do suspeito à vítima", "A escolha livre feita pelo policial", "O depoimento do próprio suspeito"], "explicacao": "Art. 226, I, do CPP."}, {"id": 10590, "materia": "ppen", "nivel": 1, "enunciado": "O policial que, sem mandado, entra numa casa onde está ocorrendo um crime de tráfico em andamento age:", "opcoes": ["Licitamente, pelo flagrante delito", "Ilicitamente, pois precisa de mandado", "Licitamente, só se for de dia", "Ilicitamente, se o morador não autorizar"], "explicacao": "Flagrante permite entrar a qualquer hora (art. 5º, XI, da CF), desde que haja fundadas razões."}, {"id": 10591, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a lei punirá qualquer discriminação que atente contra os:", "opcoes": ["Direitos e liberdades fundamentais", "Interesses das empresas", "Símbolos e cores dos clubes de futebol", "Costumes de cada bairro"], "explicacao": "Art. 5º, XLI, da CF."}, {"id": 10592, "materia": "const", "nivel": 0, "enunciado": "A Constituição garante a livre manifestação do pensamento, mas proíbe o:", "opcoes": ["Anonimato", "Uso de redes sociais", "Direito de resposta", "Uso de jornais"], "explicacao": "Art. 5º, IV, da CF."}, {"id": 10593, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, às presidiárias serão asseguradas condições para:", "opcoes": ["Permanecer com os filhos durante a amamentação", "Cumprir a pena sempre em casa", "Escolher a cela onde vão ficar", "Sair do presídio todos os fins de semana com a família"], "explicacao": "Art. 5º, L, da CF."}, {"id": 10594, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, NÃO haverá pena de:", "opcoes": ["Caráter perpétuo", "Multa", "Prestação de serviços à comunidade", "Privação da liberdade"], "explicacao": "Art. 5º, XLVII, da CF."}, {"id": 10595, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a casa é asilo inviolável, mas nela se pode entrar sem consentimento do morador, durante a noite, em caso de:", "opcoes": ["Flagrante delito", "Cumprimento de mandado judicial", "Fiscalização sanitária de rotina", "Intimação para depor"], "explicacao": "Art. 5º, XI: à noite só flagrante, desastre ou socorro; ordem judicial só durante o dia."}, {"id": 10596, "materia": "const", "nivel": 0, "enunciado": "O voto no Brasil, para maiores de 18 anos e menores de 70, é:", "opcoes": ["Obrigatório", "Facultativo", "Proibido", "Facultativo só para servidores"], "explicacao": "Art. 14, § 1º, da CF."}, {"id": 10597, "materia": "const", "nivel": 0, "enunciado": "A Polícia Federal integra a estrutura da:", "opcoes": ["União", "Estados", "Municípios", "Forças Armadas"], "explicacao": "Art. 144, § 1º, da CF."}, {"id": 10598, "materia": "const", "nivel": 0, "enunciado": "A Constituição garante a reunião pacífica, sem armas, em locais abertos, exigindo apenas:", "opcoes": ["Aviso prévio à autoridade", "Autorização do juiz", "Pagamento de taxa à prefeitura", "Idade mínima de 21 anos"], "explicacao": "Art. 5º, XVI: independe de autorização."}, {"id": 10599, "materia": "const", "nivel": 0, "enunciado": "O patrulhamento ostensivo das rodovias federais é feito pela:", "opcoes": ["Polícia Rodoviária Federal", "Polícia Federal", "Polícia Militar", "Força Nacional"], "explicacao": "Art. 144, § 2º, da CF."}, {"id": 10600, "materia": "const", "nivel": 0, "enunciado": "A segurança das unidades do sistema prisional cabe às:", "opcoes": ["Polícias penais", "Polícias civis", "Guardas municipais", "Polícias militares"], "explicacao": "Art. 144, § 5º-A, incluído pela EC 104/2019."}, {"id": 10601, "materia": "const", "nivel": 1, "enunciado": "Os municípios podem constituir guardas municipais destinadas, segundo a Constituição, à proteção de:", "opcoes": ["Seus bens, serviços e instalações", "Rodovias federais", "Fronteiras terrestres e marítimas do país", "Presídios estaduais"], "explicacao": "Art. 144, § 8º, da CF."}, {"id": 10602, "materia": "const", "nivel": 1, "enunciado": "Entre as penas que a Constituição admite está a de:", "opcoes": ["Perda de bens", "Banimento", "Trabalhos forçados", "Morte em tempo de paz"], "explicacao": "Art. 5º, XLVI e XLVII, da CF."}, {"id": 10603, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, os direitos políticos ficam suspensos em caso de:", "opcoes": ["Condenação criminal transitada em julgado", "Mudança de endereço", "Falta a uma eleição", "Prisão em flagrante, ainda sem julgamento"], "explicacao": "Art. 15, III, da CF, enquanto durarem os efeitos."}, {"id": 10604, "materia": "const", "nivel": 1, "enunciado": "São inafiançáveis e insuscetíveis de graça ou anistia, entre outros:", "opcoes": ["Tortura, tráfico de drogas e terrorismo", "Furto, roubo e estelionato", "Homicídio culposo e lesão corporal leve", "Calúnia, injúria e difamação"], "explicacao": "Art. 5º, XLIII, da CF (e crimes hediondos)."}, {"id": 10605, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, o civilmente identificado não será identificado criminalmente, salvo:", "opcoes": ["Nas hipóteses previstas em lei", "Sempre que o delegado entender conveniente", "Em qualquer prisão", "Se a vítima pedir"], "explicacao": "Art. 5º, LVIII, da CF e Lei 12.037/2009."}, {"id": 10606, "materia": "const", "nivel": 1, "enunciado": "O cidadão que quer anular ato lesivo ao patrimônio público pode propor:", "opcoes": ["Ação popular", "Habeas data", "Habeas corpus", "Mandado de injunção"], "explicacao": "Art. 5º, LXXIII, da CF."}, {"id": 10607, "materia": "const", "nivel": 1, "enunciado": "A pena NÃO passará da pessoa do condenado, mas a obrigação de reparar o dano pode ser estendida:", "opcoes": ["Aos sucessores, até o limite do patrimônio transferido", "A qualquer parente, sem limite de valor nenhum", "Apenas ao cônjuge do condenado", "Ao Estado, que paga a vítima"], "explicacao": "Art. 5º, XLV, da CF."}, {"id": 10608, "materia": "const", "nivel": 1, "enunciado": "Cabe à Polícia Federal prevenir e reprimir, entre outros, o crime de:", "opcoes": ["Tráfico ilícito de drogas", "Furto em loja de bairro", "Lesão corporal leve", "Briga entre vizinhos"], "explicacao": "Art. 144, § 1º, II, da CF."}, {"id": 10609, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, quem nasce no Brasil, filho de pais estrangeiros que não estão a serviço de seu país, é:", "opcoes": ["Brasileiro nato", "Estrangeiro residente", "Brasileiro naturalizado", "Apátrida"], "explicacao": "Art. 12, I, \"a\", da CF."}, {"id": 10610, "materia": "const", "nivel": 1, "enunciado": "A Constituição assegura ao Tribunal do Júri, entre outros:", "opcoes": ["O sigilo das votações", "O voto aberto dos jurados", "A presença da imprensa na votação", "A escolha dos jurados pelo réu"], "explicacao": "Art. 5º, XXXVIII, da CF."}, {"id": 10611, "materia": "adm", "nivel": 0, "enunciado": "O princípio que obriga a Administração a fazer apenas o que a lei permite é o da:", "opcoes": ["Legalidade", "Publicidade", "Eficiência", "Moralidade"], "explicacao": "Art. 37 da CF."}, {"id": 10612, "materia": "adm", "nivel": 0, "enunciado": "Tratar todos os cidadãos sem favoritismo nem perseguição atende ao princípio da:", "opcoes": ["Impessoalidade", "Publicidade", "Eficiência", "Legalidade"], "explicacao": "A Administração não pode agir por interesse pessoal."}, {"id": 10613, "materia": "adm", "nivel": 0, "enunciado": "Buscar o melhor resultado com menos gasto de recursos atende ao princípio da:", "opcoes": ["Eficiência", "Moralidade", "Publicidade", "Impessoalidade"], "explicacao": "Incluído no art. 37 pela EC 19/1998."}, {"id": 10614, "materia": "adm", "nivel": 0, "enunciado": "A forma de ingresso em cargo público efetivo, em regra, é o:", "opcoes": ["Concurso público", "Indicação política", "Sorteio entre interessados", "Contrato verbal"], "explicacao": "Art. 37, II, da CF."}, {"id": 10615, "materia": "adm", "nivel": 0, "enunciado": "O poder de editar decretos para a fiel execução das leis é o poder:", "opcoes": ["Regulamentar", "Disciplinar", "De polícia", "Hierárquico"], "explicacao": "Art. 84, IV, da CF."}, {"id": 10616, "materia": "adm", "nivel": 0, "enunciado": "A Administração Pública direta é formada por:", "opcoes": ["União, estados, DF e municípios", "Autarquias, fundações e empresas públicas", "Empresas privadas", "Bancos estrangeiros"], "explicacao": "Os próprios entes federativos e seus órgãos."}, {"id": 10617, "materia": "adm", "nivel": 0, "enunciado": "Empresas públicas e sociedades de economia mista fazem parte da Administração:", "opcoes": ["Indireta", "Direta", "Centralizada", "Privada"], "explicacao": "Junto com autarquias e fundações públicas."}, {"id": 10618, "materia": "adm", "nivel": 0, "enunciado": "A licitação serve, principalmente, para:", "opcoes": ["Escolher a proposta mais vantajosa ao órgão", "Contratar sempre a empresa mais conhecida do mercado", "Favorecer as empresas da própria cidade do órgão", "Dispensar a fiscalização"], "explicacao": "Lei 14.133/2021."}, {"id": 10619, "materia": "adm", "nivel": 0, "enunciado": "O cargo em comissão é de livre nomeação e livre:", "opcoes": ["Exoneração", "Concurso", "Estabilidade", "Sorteio"], "explicacao": "Art. 37, II, da CF."}, {"id": 10620, "materia": "adm", "nivel": 1, "enunciado": "A retirada de um ato válido por conveniência e oportunidade é a:", "opcoes": ["Revogação", "Anulação", "Cassação", "Caducidade"], "explicacao": "A revogação produz efeitos a partir de então (ex nunc)."}, {"id": 10621, "materia": "adm", "nivel": 1, "enunciado": "O atributo que faz o ato administrativo ser considerado verdadeiro e legal até prova em contrário é a:", "opcoes": ["Presunção de legitimidade", "Autoexecutoriedade absoluta", "Imperatividade", "Tipicidade"], "explicacao": "É uma presunção relativa: admite prova em contrário."}, {"id": 10622, "materia": "adm", "nivel": 1, "enunciado": "Na responsabilidade objetiva do Estado, a vítima NÃO precisa provar:", "opcoes": ["A culpa do agente público", "O dano que sofreu", "O nexo entre a conduta e o dano", "Que o fato realmente ocorreu"], "explicacao": "Basta provar conduta, dano e nexo causal."}, {"id": 10623, "materia": "adm", "nivel": 1, "enunciado": "O Estado que indeniza a vítima pode cobrar do servidor causador do dano quando este agiu com:", "opcoes": ["Dolo ou culpa", "Qualquer conduta, mesmo sem culpa", "Apenas dolo", "Apenas culpa grave"], "explicacao": "Ação regressiva (art. 37, § 6º, da CF)."}, {"id": 10624, "materia": "adm", "nivel": 1, "enunciado": "Uma autarquia é criada por meio de:", "opcoes": ["Lei específica", "Decreto do governador", "Portaria do secretário", "Contrato social"], "explicacao": "Art. 37, XIX, da CF."}, {"id": 10625, "materia": "adm", "nivel": 1, "enunciado": "Se o motivo alegado para um ato administrativo é falso, o ato é:", "opcoes": ["Nulo, pela teoria dos motivos determinantes", "Válido, pois o motivo declarado não importa", "Válido, se a autoridade quiser", "Revogável apenas pelo Judiciário"], "explicacao": "O motivo declarado vincula a validade do ato."}, {"id": 10626, "materia": "adm", "nivel": 1, "enunciado": "Extinto o cargo, o servidor estável fica sem trabalhar, com remuneração proporcional, na situação de:", "opcoes": ["Disponibilidade", "Exoneração", "Demissão", "Aposentadoria"], "explicacao": "Art. 41, § 3º, da CF."}, {"id": 10627, "materia": "adm", "nivel": 1, "enunciado": "Após a Lei 14.230/2021, para haver ato de improbidade é necessário:", "opcoes": ["Conduta dolosa do agente", "Apenas culpa leve", "Qualquer erro do servidor", "Prejuízo acima de R$ 1 milhão"], "explicacao": "A modalidade culposa foi extinta."}, {"id": 10628, "materia": "adm", "nivel": 1, "enunciado": "O ato administrativo que pode ser praticado com margem de escolha quanto à conveniência e à oportunidade é o:", "opcoes": ["Discricionário", "Vinculado", "Nulo", "Inexistente"], "explicacao": "No vinculado, a lei não deixa margem de escolha."}, {"id": 10629, "materia": "leg", "nivel": 0, "enunciado": "A Lei Maria da Penha (Lei 11.340/2006) protege principalmente:", "opcoes": ["A mulher em situação de violência doméstica e familiar", "Crianças e adolescentes em situação de rua e abandono", "Idosos em asilos", "Trabalhadores rurais"], "explicacao": "A lei cria mecanismos para coibir a violência doméstica contra a mulher."}, {"id": 10630, "materia": "leg", "nivel": 0, "enunciado": "O Estatuto do Desarmamento é a Lei:", "opcoes": ["10.826/2003", "11.343/2006", "8.072/1990", "9.455/1997"], "explicacao": "A Lei 10.826/2003 trata de armas de fogo e munições."}, {"id": 10631, "materia": "leg", "nivel": 0, "enunciado": "O tráfico ilícito de drogas é crime:", "opcoes": ["Equiparado a hediondo", "De menor potencial ofensivo", "Culposo", "Afiançável pelo delegado"], "explicacao": "Art. 5º, XLIII, da CF e Lei 8.072/1990."}, {"id": 10632, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei Maria da Penha, a violência praticada pelo namorado, mesmo sem morarem juntos:", "opcoes": ["Também é protegida pela lei", "Não é protegida pela lei", "Só vale se houver filhos", "Só vale após 5 anos de namoro"], "explicacao": "Art. 5º, III, da Lei 11.340/2006 e Súmula 600 do STJ."}, {"id": 10633, "materia": "leg", "nivel": 0, "enunciado": "O crime de tortura é considerado:", "opcoes": ["Equiparado a hediondo", "Infração de menor potencial ofensivo", "Contravenção penal", "Crime culposo"], "explicacao": "Art. 5º, XLIII, da CF e art. 2º da Lei 8.072/1990."}, {"id": 10634, "materia": "leg", "nivel": 0, "enunciado": "Pelo ECA, ao adolescente que pratica ato infracional aplica-se medida:", "opcoes": ["Socioeducativa", "Penal", "Prisional", "Disciplinar"], "explicacao": "Art. 112 do ECA."}, {"id": 10635, "materia": "leg", "nivel": 0, "enunciado": "O ato do adolescente que corresponde a um crime é chamado, pelo ECA, de:", "opcoes": ["Ato infracional", "Contravenção penal", "Crime juvenil", "Delito menor"], "explicacao": "Art. 103 do ECA."}, {"id": 10636, "materia": "leg", "nivel": 0, "enunciado": "O latrocínio (roubo seguido de morte) é crime:", "opcoes": ["Hediondo", "De menor potencial ofensivo", "Culposo", "Afiançável pelo delegado"], "explicacao": "Art. 1º, II, \"c\", da Lei 8.072/1990."}, {"id": 10637, "materia": "leg", "nivel": 0, "enunciado": "Pelo Estatuto do Desarmamento, o porte de arma de fogo é, em regra:", "opcoes": ["Proibido no país, salvo os casos previstos em lei", "Livre para maiores de 18 anos", "Permitido só nas capitais", "Liberado a quem tiver posse de arma registrada em casa"], "explicacao": "Art. 6º da Lei 10.826/2003."}, {"id": 10638, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei 12.850/2013, o acordo em que o investigado ajuda a investigação em troca de benefícios é a:", "opcoes": ["Colaboração premiada", "Transação penal", "Suspensão condicional", "Delação anônima"], "explicacao": "Arts. 3º-A a 7º da Lei 12.850/2013."}, {"id": 10639, "materia": "leg", "nivel": 0, "enunciado": "Os Juizados Especiais Criminais julgam as infrações de:", "opcoes": ["Menor potencial ofensivo", "Natureza hedionda", "Competência do júri", "Natureza militar"], "explicacao": "Lei 9.099/1995."}, {"id": 10640, "materia": "leg", "nivel": 1, "enunciado": "Na Lei 9.099/1995, o acordo em que o MP propõe multa ou pena restritiva de direitos, sem processo, é a:", "opcoes": ["Transação penal", "Colaboração premiada", "Suspensão condicional da pena", "Composição civil dos danos"], "explicacao": "Art. 76 da Lei 9.099/1995."}, {"id": 10641, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, nos crimes de violência doméstica contra a mulher, NÃO se aplica:", "opcoes": ["A Lei 9.099/1995", "O Código Penal", "O Código de Processo Penal", "A Constituição Federal"], "explicacao": "Art. 41 da Lei 11.340/2006 e Súmula 536 do STJ."}, {"id": 10642, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, a violência doméstica pode ser física, psicológica, sexual, moral e:", "opcoes": ["Patrimonial", "Ambiental", "Tributária", "Digital apenas"], "explicacao": "Art. 7º da Lei 11.340/2006."}, {"id": 10643, "materia": "leg", "nivel": 1, "enunciado": "Pelo Estatuto do Desarmamento, manter arma de uso permitido, sem registro, dentro de casa configura:", "opcoes": ["Posse irregular de arma de fogo", "Porte ilegal de arma de fogo", "Disparo de arma de fogo", "Comércio ilegal de arma"], "explicacao": "Art. 12 da Lei 10.826/2003. Fora de casa seria porte (art. 14)."}, {"id": 10644, "materia": "leg", "nivel": 1, "enunciado": "Disparar arma de fogo em via pública, sem ter como finalidade outro crime, configura:", "opcoes": ["Crime do art. 15 do Estatuto do Desarmamento", "Contravenção penal de perturbação do sossego alheio", "Tentativa de homicídio, sempre", "Fato atípico, se ninguém se ferir"], "explicacao": "Art. 15 da Lei 10.826/2003."}, {"id": 10645, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei de Drogas, oferecer droga, sem lucro, a pessoa do seu relacionamento, para consumirem juntos, configura:", "opcoes": ["Crime com pena menor (art. 33, § 3º)", "Tráfico comum, com pena de 5 a 15 anos", "Porte para consumo pessoal", "Fato atípico"], "explicacao": "Art. 33, § 3º, da Lei 11.343/2006."}, {"id": 10646, "materia": "leg", "nivel": 1, "enunciado": "Na Lei de Tortura, a pena aumenta de um sexto até um terço se o crime é cometido:", "opcoes": ["Por agente público", "Durante o dia", "Sem uso de arma", "Por motivo de vingança"], "explicacao": "Art. 1º, § 4º, I, da Lei 9.455/1997."}, {"id": 10647, "materia": "leg", "nivel": 1, "enunciado": "Pelo ECA, a liberdade assistida tem prazo mínimo de:", "opcoes": ["6 meses", "1 mês", "1 ano", "3 anos"], "explicacao": "Art. 118, § 2º, do ECA."}, {"id": 10648, "materia": "leg", "nivel": 1, "enunciado": "No crime hediondo, a pena começa a ser cumprida, segundo o STF:", "opcoes": ["Em regime definido pelo juiz conforme o caso", "Sempre em regime fechado, sem exceção alguma", "Sempre em regime aberto", "Em liberdade condicional"], "explicacao": "O STF declarou inconstitucional o regime inicial fechado obrigatório (HC 111.840)."}, {"id": 10649, "materia": "leg", "nivel": 1, "enunciado": "Pelo Código de Trânsito, dirigir sem habilitação gerando perigo de dano configura:", "opcoes": ["Crime do art. 309 do CTB", "Apenas infração administrativa", "Contravenção penal", "Crime de embriaguez ao volante"], "explicacao": "Art. 309 do CTB exige perigo de dano."}, {"id": 10650, "materia": "leg", "nivel": 1, "enunciado": "O crime de racismo é previsto na Lei:", "opcoes": ["7.716/1989", "9.455/1997", "8.072/1990", "10.741/2003"], "explicacao": "Lei 7.716/1989."}, {"id": 10651, "materia": "port", "nivel": 0, "enunciado": "Assinale a palavra com grafia correta:", "opcoes": ["Paralisação", "Paralização", "Paralizasão", "Paralisasão"], "explicacao": "Vem de \"paralisar\", com s."}, {"id": 10652, "materia": "port", "nivel": 0, "enunciado": "Assinale a palavra com grafia correta:", "opcoes": ["Beneficente", "Beneficiente", "Benificente", "Benefisciente"], "explicacao": "Beneficente, sem \"i\" depois do \"c\"."}, {"id": 10653, "materia": "port", "nivel": 0, "enunciado": "Assinale a frase com o verbo \"haver\" usado corretamente:", "opcoes": ["Houve dois assaltos ontem", "Houveram dois assaltos ontem", "Haviam dois suspeitos na sala", "Devem haver testemunhas"], "explicacao": "Haver no sentido de existir ou acontecer é impessoal."}, {"id": 10654, "materia": "port", "nivel": 0, "enunciado": "Em \"O policial chegou cedo\", o sujeito é:", "opcoes": ["O policial", "Cedo", "Chegou", "Inexistente"], "explicacao": "Quem chegou: o policial."}, {"id": 10655, "materia": "port", "nivel": 0, "enunciado": "Assinale a frase em que o \"porquê\" está correto:", "opcoes": ["Não sei o porquê da demora", "Por quê você chegou tarde?", "Estudo porquê quero passar", "Ele saiu, por que?"], "explicacao": "\"O porquê\" é substantivo, com artigo."}, {"id": 10656, "materia": "port", "nivel": 0, "enunciado": "Na frase \"O agente chegou ontem\", a palavra \"ontem\" indica:", "opcoes": ["Tempo", "Lugar", "Modo", "Intensidade"], "explicacao": "Advérbio de tempo."}, {"id": 10657, "materia": "port", "nivel": 0, "enunciado": "Em \"O juiz expediu o mandado\", o verbo \"expedir\" significa:", "opcoes": ["Emitir", "Rasgar", "Esconder", "Atrasar"], "explicacao": "Expedir = emitir, enviar."}, {"id": 10658, "materia": "port", "nivel": 0, "enunciado": "Qual palavra é acentuada pela mesma regra de \"inquérito\"?", "opcoes": ["Público", "Café", "Lápis", "Saúde"], "explicacao": "Ambas são proparoxítonas; todas as proparoxítonas levam acento."}, {"id": 10659, "materia": "port", "nivel": 0, "enunciado": "Em \"Vou à delegacia\", o acento grave indica:", "opcoes": ["Crase", "Tempo verbal", "Ênfase", "Plural"], "explicacao": "Ir a + a delegacia = à delegacia."}, {"id": 10660, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase em que \"mas\" e \"mais\" estão corretos:", "opcoes": ["Ele estudou, mas não passou", "Ele estudou, mais não passou", "Quero mas tempo para estudar", "Ele é mas rápido que eu"], "explicacao": "\"Mas\" opõe ideias; \"mais\" indica quantidade."}, {"id": 10661, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase correta quanto à crase:", "opcoes": ["Entreguei o laudo à perita", "Comecei à estudar cedo", "Fui à pé até o fórum", "Falei à uma testemunha"], "explicacao": "Não há crase antes de verbo, palavra masculina ou artigo indefinido."}, {"id": 10662, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase correta quanto à regência:", "opcoes": ["Assisti ao jogo ontem", "Assisti o jogo ontem", "Prefiro mais café do que chá", "Cheguei no fórum cedo"], "explicacao": "Assistir (ver) pede a preposição \"a\"."}, {"id": 10663, "materia": "port", "nivel": 1, "enunciado": "Em \"Embora estivesse cansado, ele estudou\", a palavra \"embora\" indica:", "opcoes": ["Concessão", "Causa", "Conclusão", "Finalidade"], "explicacao": "Embora introduz ideia contrária que não impede o fato."}, {"id": 10664, "materia": "port", "nivel": 1, "enunciado": "Em \"Se chover, a operação será adiada\", a palavra \"se\" indica:", "opcoes": ["Condição", "Causa", "Concessão", "Consequência"], "explicacao": "Conjunção condicional."}, {"id": 10665, "materia": "port", "nivel": 1, "enunciado": "Assinale a colocação pronominal correta:", "opcoes": ["Não me disseram nada", "Me disseram tudo ontem", "Ninguém disse-me nada", "Tinha dito-me a verdade"], "explicacao": "A negação atrai o pronome; não se começa frase com pronome oblíquo."}, {"id": 10666, "materia": "port", "nivel": 1, "enunciado": "Na frase \"O laudo foi assinado pelo perito\", a voz verbal é:", "opcoes": ["Passiva analítica", "Ativa", "Reflexiva", "Passiva sintética"], "explicacao": "Verbo ser + particípio + agente da passiva."}, {"id": 10667, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase pontuada corretamente:", "opcoes": ["Os peritos, que chegaram cedo, isolaram a área", "Os peritos que chegaram cedo, isolaram a área", "Os peritos, isolaram a área", "O delegado determinou, a prisão"], "explicacao": "Não se separa sujeito do verbo nem verbo do complemento com vírgula."}, {"id": 10668, "materia": "port", "nivel": 1, "enunciado": "Em \"Ele mal chegou e já saiu\", a palavra \"mal\" significa:", "opcoes": ["Assim que, logo que", "De forma errada", "Doença", "Algo ruim"], "explicacao": "\"Mal\" indica tempo: assim que chegou."}, {"id": 10669, "materia": "dh", "nivel": 0, "enunciado": "A Lei de Execução Penal assegura ao preso, entre outros direitos, assistência:", "opcoes": ["Material, à saúde e jurídica", "Para sair livremente aos domingos", "Para escolher o juiz do seu caso", "Para não trabalhar nem estudar"], "explicacao": "Arts. 10 e 11 da Lei 7.210/1984."}, {"id": 10670, "materia": "dh", "nivel": 0, "enunciado": "O Brasil promulgou a Convenção Americana sobre Direitos Humanos (Pacto de San José) em:", "opcoes": ["1992", "1948", "1964", "2010"], "explicacao": "Decreto 678/1992."}, {"id": 10671, "materia": "dh", "nivel": 0, "enunciado": "Pelos direitos humanos, a pessoa presa:", "opcoes": ["Mantém os direitos não atingidos pela pena", "Perde todos os direitos enquanto estiver presa", "Perde o direito à saúde", "Pode receber castigo físico se desobedecer"], "explicacao": "Art. 3º da LEP e Regras de Mandela."}, {"id": 10672, "materia": "dh", "nivel": 0, "enunciado": "A proibição da tortura, segundo os tratados internacionais, é:", "opcoes": ["Absoluta, sem exceção", "Permitida em guerra", "Permitida contra terroristas", "Permitida com ordem judicial"], "explicacao": "Nenhuma circunstância justifica a tortura."}, {"id": 10673, "materia": "dh", "nivel": 0, "enunciado": "Tratados de direitos humanos aprovados no Congresso pelo rito especial de emenda têm status de:", "opcoes": ["Emenda constitucional", "Lei ordinária", "Decreto", "Portaria"], "explicacao": "Art. 5º, § 3º, da CF: dois turnos, 3/5 dos votos."}, {"id": 10674, "materia": "dh", "nivel": 1, "enunciado": "Pela Convenção Americana, toda pessoa presa deve ser levada sem demora à presença de:", "opcoes": ["Um juiz", "Um jornalista", "Um parente", "Um vereador"], "explicacao": "Art. 7.5 da Convenção, base da audiência de custódia."}, {"id": 10675, "materia": "dh", "nivel": 1, "enunciado": "A Comissão Interamericana de Direitos Humanos tem sede em:", "opcoes": ["Washington, nos EUA", "San José, na Costa Rica", "Genebra, na Suíça", "Brasília, no Brasil"], "explicacao": "A Corte Interamericana é que fica em San José."}, {"id": 10676, "materia": "dh", "nivel": 1, "enunciado": "As Diretrizes de Riad, da ONU, tratam da prevenção da:", "opcoes": ["Delinquência juvenil", "Tortura em presídios", "Violência contra a mulher", "Discriminação racial"], "explicacao": "Diretrizes das Nações Unidas para a Prevenção da Delinquência Juvenil (1990)."}, {"id": 10677, "materia": "dh", "nivel": 1, "enunciado": "Por causa do Pacto de San José, o STF considera ilícita a prisão civil do:", "opcoes": ["Depositário infiel", "Devedor de pensão alimentícia", "Preso em flagrante", "Condenado por tráfico"], "explicacao": "Súmula Vinculante 25."}, {"id": 10678, "materia": "dh", "nivel": 1, "enunciado": "A Lei 9.455/1997, que define os crimes de tortura, cumpre compromisso assumido pelo Brasil em:", "opcoes": ["Convenção da ONU contra a Tortura", "Acordo de cooperação policial do Mercosul", "Tratado de Itaipu", "Protocolo de Kyoto"], "explicacao": "Convenção contra a Tortura de 1984."}, {"id": 10679, "materia": "inf", "nivel": 0, "enunciado": "Numa planilha, a célula na coluna C, linha 7, é identificada como:", "opcoes": ["C7", "7C", "L7C3", "C:7"], "explicacao": "Primeiro a letra da coluna, depois o número da linha."}, {"id": 10680, "materia": "inf", "nivel": 0, "enunciado": "Ao salvar um arquivo com outro nome, mantendo o original, usa-se a opção:", "opcoes": ["Salvar como", "Salvar", "Desfazer", "Fechar"], "explicacao": "\"Salvar como\" cria uma cópia com novo nome ou local."}, {"id": 10681, "materia": "inf", "nivel": 0, "enunciado": "Um arquivo com extensão .pdf é, em geral, um:", "opcoes": ["Documento", "Programa", "Vídeo", "Áudio"], "explicacao": "PDF é formato de documento."}, {"id": 10682, "materia": "inf", "nivel": 0, "enunciado": "O e-mail falso que imita um banco para roubar senhas é chamado de:", "opcoes": ["Phishing", "Backup", "Firewall", "Cookie"], "explicacao": "Golpe de engenharia social."}, {"id": 10683, "materia": "inf", "nivel": 0, "enunciado": "No Excel, toda fórmula começa com o sinal:", "opcoes": ["=", "#", "@", "&"], "explicacao": "Ex.: =SOMA(A1:A5)."}, {"id": 10684, "materia": "inf", "nivel": 0, "enunciado": "Guardar uma cópia dos arquivos para recuperar em caso de perda é fazer:", "opcoes": ["Backup", "Download", "Spam", "Upload de vírus"], "explicacao": "Backup é cópia de segurança."}, {"id": 10685, "materia": "inf", "nivel": 1, "enunciado": "O malware que sequestra arquivos e pede resgate é o:", "opcoes": ["Ransomware", "Spyware", "Adware", "Worm"], "explicacao": "Ransomware criptografa dados e exige pagamento."}, {"id": 10686, "materia": "inf", "nivel": 1, "enunciado": "No Excel, a função =MÉDIA(A1:A3), com os valores 4, 6 e 8, retorna:", "opcoes": ["6", "18", "4", "8"], "explicacao": "(4 + 6 + 8) / 3 = 6."}, {"id": 10687, "materia": "inf", "nivel": 1, "enunciado": "O recurso que filtra o tráfego da rede e bloqueia acessos não autorizados é o:", "opcoes": ["Firewall", "Navegador", "Cookie", "Proxy de impressão"], "explicacao": "Firewall controla conexões de entrada e saída."}, {"id": 10688, "materia": "inf", "nivel": 1, "enunciado": "Para enviar um e-mail a vários destinatários sem que um veja o endereço do outro, usa-se o campo:", "opcoes": ["Cco", "Cc", "Para", "Assunto"], "explicacao": "Cópia oculta."}, {"id": 10689, "materia": "inf", "nivel": 1, "enunciado": "O cadeado e o \"https\" na barra do navegador indicam que:", "opcoes": ["A conexão com o site é criptografada", "O site é seguro e não pode ser um golpe", "O site é do governo", "O computador está sem vírus"], "explicacao": "HTTPS protege a comunicação, mas não garante que o site é honesto."}, {"id": 10690, "materia": "inf", "nivel": 1, "enunciado": "A autenticação em dois fatores combina a senha com:", "opcoes": ["Um código enviado a um aparelho do usuário", "Outra senha igual à primeira, digitada de novo", "O nome do usuário", "A data de nascimento"], "explicacao": "Algo que você sabe + algo que você tem."}, {"id": 10691, "materia": "rl", "nivel": 0, "enunciado": "Se hoje é quarta-feira, daqui a 15 dias será:", "opcoes": ["Quinta-feira", "Quarta-feira", "Sexta-feira", "Terça-feira"], "explicacao": "14 dias depois é quarta de novo; mais 1 dia, quinta."}, {"id": 10692, "materia": "rl", "nivel": 0, "enunciado": "Na sequência 2, 4, 8, 16, ..., o próximo número é:", "opcoes": ["32", "24", "20", "30"], "explicacao": "Cada termo é o dobro do anterior."}, {"id": 10693, "materia": "rl", "nivel": 0, "enunciado": "Se 20% de 50 candidatos foram aprovados, o número de aprovados é:", "opcoes": ["10", "20", "5", "25"], "explicacao": "0,2 × 50 = 10."}, {"id": 10694, "materia": "rl", "nivel": 0, "enunciado": "Um agente trabalha 8 horas por dia. Em 5 dias, ele trabalha:", "opcoes": ["40 horas", "13 horas", "35 horas", "48 horas"], "explicacao": "8 × 5 = 40."}, {"id": 10695, "materia": "rl", "nivel": 0, "enunciado": "Em uma sala há 5 homens e 3 mulheres. Sorteando uma pessoa, a chance de ser mulher é:", "opcoes": ["3/8", "3/5", "5/8", "1/3"], "explicacao": "3 mulheres em 8 pessoas."}, {"id": 10696, "materia": "rl", "nivel": 0, "enunciado": "Na sequência 5, 10, 15, 20, ..., o próximo número é:", "opcoes": ["25", "30", "22", "40"], "explicacao": "Soma 5 a cada termo."}, {"id": 10697, "materia": "rl", "nivel": 1, "enunciado": "A negação de \"Nenhum preso fugiu\" é:", "opcoes": ["Algum preso fugiu", "Todos os presos fugiram", "Nenhum preso ficou", "Algum preso não fugiu"], "explicacao": "Basta um caso para negar \"nenhum\"."}, {"id": 10698, "materia": "rl", "nivel": 1, "enunciado": "A negação de \"Ana estuda e Bia trabalha\" é:", "opcoes": ["Ana não estuda ou Bia não trabalha", "Ana não estuda e Bia não trabalha", "Ana estuda ou Bia trabalha", "Se Ana estuda, Bia trabalha"], "explicacao": "Lei de De Morgan."}, {"id": 10699, "materia": "rl", "nivel": 1, "enunciado": "Uma proposição equivalente a \"Se chove, então a rua molha\" é:", "opcoes": ["Se a rua não molha, então não chove", "Se a rua molha, então chove", "Se não chove, a rua não molha", "Chove e a rua não molha"], "explicacao": "Contrapositiva."}, {"id": 10700, "materia": "rl", "nivel": 1, "enunciado": "Cinco pessoas se cumprimentam, cada par uma única vez. Quantos apertos de mão acontecem?", "opcoes": ["10", "20", "25", "5"], "explicacao": "C(5,2) = 10."}, {"id": 10701, "materia": "rl", "nivel": 1, "enunciado": "Um produto de R$ 200,00 teve desconto de 15%. O preço final é:", "opcoes": ["R$ 170,00", "R$ 185,00", "R$ 150,00", "R$ 175,00"], "explicacao": "15% de 200 = 30; 200 − 30 = 170."}, {"id": 10702, "materia": "rl", "nivel": 1, "enunciado": "Três agentes fazem uma ronda em 6 horas. Seis agentes, no mesmo ritmo, fazem a mesma ronda em:", "opcoes": ["3 horas", "12 horas", "6 horas", "2 horas"], "explicacao": "Grandezas inversamente proporcionais."}, {"id": 10703, "materia": "est", "nivel": 0, "enunciado": "A média de 4, 6 e 8 é:", "opcoes": ["6", "18", "5", "7"], "explicacao": "(4 + 6 + 8) / 3 = 6."}, {"id": 10704, "materia": "est", "nivel": 0, "enunciado": "As notas de uma turma foram 7, 7, 8, 9, 7 e 10. A moda é:", "opcoes": ["7", "8", "9", "10"], "explicacao": "O 7 aparece mais vezes."}, {"id": 10705, "materia": "est", "nivel": 0, "enunciado": "A média das idades 20, 30 e 40 anos é:", "opcoes": ["30 anos", "90 anos", "25 anos", "35 anos"], "explicacao": "(20 + 30 + 40) / 3 = 30."}, {"id": 10706, "materia": "est", "nivel": 0, "enunciado": "A amplitude do conjunto 4, 10, 7, 15 é:", "opcoes": ["11", "15", "4", "9"], "explicacao": "Maior − menor: 15 − 4 = 11."}, {"id": 10707, "materia": "est", "nivel": 1, "enunciado": "A mediana de 2, 8, 4, 6 é:", "opcoes": ["5", "4", "6", "20"], "explicacao": "Ordenado: 2, 4, 6, 8. Média dos centrais: (4 + 6) / 2 = 5."}, {"id": 10708, "materia": "est", "nivel": 1, "enunciado": "Se a variância de um conjunto é 16, o desvio padrão é:", "opcoes": ["4", "8", "16", "256"], "explicacao": "Desvio padrão é a raiz quadrada da variância."}, {"id": 10709, "materia": "est", "nivel": 1, "enunciado": "A variável \"cor dos olhos\" é classificada como:", "opcoes": ["Qualitativa nominal", "Quantitativa discreta", "Quantitativa contínua", "Qualitativa ordinal"], "explicacao": "Categorias sem ordem natural."}, {"id": 10710, "materia": "est", "nivel": 1, "enunciado": "A variável \"altura dos candidatos\" é classificada como:", "opcoes": ["Quantitativa contínua", "Quantitativa discreta", "Qualitativa nominal", "Qualitativa ordinal"], "explicacao": "Medida que pode assumir qualquer valor num intervalo."}, {"id": 10711, "materia": "cont", "nivel": 0, "enunciado": "Uma empresa compra um veículo para fazer entregas. Ele é classificado no ativo:", "opcoes": ["Imobilizado", "Circulante", "Intangível", "Realizável no curto prazo"], "explicacao": "Bem de uso durável na atividade."}, {"id": 10712, "materia": "cont", "nivel": 0, "enunciado": "O dinheiro em caixa de uma empresa é classificado no:", "opcoes": ["Ativo", "Passivo", "Patrimônio Líquido", "Resultado"], "explicacao": "Caixa é bem: ativo circulante."}, {"id": 10713, "materia": "cont", "nivel": 0, "enunciado": "As dívidas com fornecedores ficam no:", "opcoes": ["Passivo", "Ativo", "Patrimônio Líquido", "Receita"], "explicacao": "Obrigação com terceiros."}, {"id": 10714, "materia": "cont", "nivel": 0, "enunciado": "Os salários a pagar aos funcionários ficam no:", "opcoes": ["Passivo", "Ativo", "Patrimônio Líquido", "Receita"], "explicacao": "É uma obrigação da empresa."}, {"id": 10715, "materia": "cont", "nivel": 1, "enunciado": "Uma empresa com ativo de R$ 300 mil e passivo de R$ 120 mil tem patrimônio líquido de:", "opcoes": ["R$ 180 mil", "R$ 420 mil", "R$ 120 mil", "R$ 300 mil"], "explicacao": "PL = Ativo − Passivo."}, {"id": 10716, "materia": "cont", "nivel": 1, "enunciado": "Pelo regime de competência, a receita de um serviço prestado em março e recebido em abril é registrada em:", "opcoes": ["Março", "Abril", "Maio", "Na data do contrato"], "explicacao": "A receita entra no período em que o serviço foi prestado."}, {"id": 10717, "materia": "cont", "nivel": 1, "enunciado": "Na compra de mercadorias à vista, o lançamento é:", "opcoes": ["D – Estoques; C – Caixa", "D – Caixa; C – Estoques", "D – Fornecedores; C – Caixa", "D – Estoques; C – Fornecedores"], "explicacao": "Entra estoque (débito), sai dinheiro (crédito)."}, {"id": 10718, "materia": "cont", "nivel": 1, "enunciado": "O pagamento de uma dívida, sem juros, é um fato contábil:", "opcoes": ["Permutativo", "Modificativo aumentativo", "Modificativo diminutivo", "Misto"], "explicacao": "Diminui ativo e passivo sem alterar o PL."}, {"id": 10719, "materia": "ml", "nivel": 0, "enunciado": "Pela Lei de Nysten, a rigidez cadavérica começa, em regra, pela:", "opcoes": ["Mandíbula e face", "Planta dos pés", "Região lombar", "Mão esquerda"], "explicacao": "Segue de cima para baixo: face, nuca, tronco e membros."}, {"id": 10720, "materia": "ml", "nivel": 0, "enunciado": "O ramo da Medicina Legal que estuda as lesões causadas por agentes externos é a:", "opcoes": ["Traumatologia", "Tanatologia", "Psicopatologia", "Antropologia"], "explicacao": "Estuda instrumentos e lesões."}, {"id": 10721, "materia": "ml", "nivel": 0, "enunciado": "O DNA é muito usado na identificação de pessoas porque:", "opcoes": ["É único, salvo em gêmeos idênticos", "Muda completamente a cada ano de vida", "É sempre igual entre irmãos e primos", "Desaparece logo após a morte"], "explicacao": "Gêmeos idênticos têm o mesmo DNA."}, {"id": 10722, "materia": "ml", "nivel": 0, "enunciado": "O instrumento que tem ponta e gume, como a faca, é classificado como:", "opcoes": ["Perfurocortante", "Contundente", "Perfurante", "Cortocontundente"], "explicacao": "Perfura e corta ao mesmo tempo."}, {"id": 10723, "materia": "ml", "nivel": 0, "enunciado": "O projétil de arma de fogo é classificado como instrumento:", "opcoes": ["Perfurocontundente", "Cortante", "Perfurocortante", "Cortocontundente"], "explicacao": "Perfura e contunde."}, {"id": 10724, "materia": "ml", "nivel": 1, "enunciado": "A asfixia por constrição do pescoço com as mãos é a:", "opcoes": ["Esganadura", "Enforcamento", "Estrangulamento", "Sufocação"], "explicacao": "Deixa marcas de dedos e unhas, sem sulco."}, {"id": 10725, "materia": "ml", "nivel": 1, "enunciado": "No enforcamento, a força que aperta o laço vem:", "opcoes": ["Do peso do próprio corpo", "Das mãos do agressor", "De uma máquina", "Da água"], "explicacao": "No estrangulamento, a força é de terceiro ou mecânica."}, {"id": 10726, "materia": "ml", "nivel": 1, "enunciado": "A lesão corporal seguida de morte, quando o agente não quis nem assumiu o risco de matar, é crime:", "opcoes": ["Preterdoloso", "Culposo", "De homicídio doloso", "Impossível"], "explicacao": "Art. 129, § 3º: dolo na lesão e culpa no resultado morte."}, {"id": 10727, "materia": "ml", "nivel": 1, "enunciado": "A lesão corporal que causa perigo de vida é classificada como:", "opcoes": ["Grave", "Leve", "Gravíssima", "Simples"], "explicacao": "Art. 129, § 1º, II, do CP."}, {"id": 10728, "materia": "ml", "nivel": 1, "enunciado": "A ferida produzida por instrumento cortante, como lâmina de barbear, é chamada de:", "opcoes": ["Incisa", "Contusa", "Perfurocontusa", "Lacerante"], "explicacao": "Bordas regulares, mais comprida que profunda."}, {"id": 10729, "materia": "igual", "nivel": 0, "enunciado": "A Lei 14.611/2023 trata da igualdade salarial entre:", "opcoes": ["Mulheres e homens", "Servidores e empregados", "Jovens e idosos", "Brasileiros e estrangeiros"], "explicacao": "Igualdade salarial e de critérios de remuneração."}, {"id": 10730, "materia": "igual", "nivel": 0, "enunciado": "A Lei 11.645/2008 incluiu nas escolas, além da cultura afro-brasileira, o ensino de história e cultura:", "opcoes": ["Indígena", "Europeia", "Asiática", "Norte-americana"], "explicacao": "Alterou a LDB."}, {"id": 10731, "materia": "igual", "nivel": 0, "enunciado": "O feminicídio é o crime de matar uma mulher:", "opcoes": ["Por razões da condição do sexo feminino", "Em qualquer situação de violência contra pessoa", "Apenas em assalto", "Somente no trânsito"], "explicacao": "Art. 121-A do CP."}, {"id": 10732, "materia": "igual", "nivel": 1, "enunciado": "O programa Sinal Vermelho, em que a mulher mostra um X na mão para pedir ajuda, foi instituído pela Lei:", "opcoes": ["14.188/2021", "11.340/2006", "13.104/2015", "12.288/2010"], "explicacao": "A mesma lei criou o crime de violência psicológica."}, {"id": 10733, "materia": "igual", "nivel": 1, "enunciado": "Após a Lei 14.994/2024, a pena do feminicídio passou a ser de:", "opcoes": ["20 a 40 anos de reclusão", "12 a 30 anos de reclusão", "6 a 20 anos de reclusão", "8 a 15 anos de reclusão"], "explicacao": "Feminicídio virou crime autônomo (art. 121-A)."}, {"id": 10734, "materia": "igual", "nivel": 1, "enunciado": "Causar dano emocional à mulher por humilhação, controle ou isolamento é crime de:", "opcoes": ["Violência psicológica (art. 147-B do CP)", "Ameaça", "Injúria simples", "Constrangimento ilegal (art. 146 do CP)"], "explicacao": "Criado pela Lei 14.188/2021."}, {"id": 10735, "materia": "pcd", "nivel": 0, "enunciado": "O cão-guia que acompanha pessoa com deficiência visual pode entrar:", "opcoes": ["Em locais de uso coletivo", "Apenas em parques e praças", "Somente em hospitais", "Em nenhum local fechado"], "explicacao": "Lei 11.126/2005, inclusive em locais privados de uso coletivo."}, {"id": 10736, "materia": "pcd", "nivel": 0, "enunciado": "O Símbolo Internacional de Acesso indica:", "opcoes": ["Locais acessíveis a quem tem deficiência", "Áreas proibidas para pedestres e ciclistas", "Saídas de emergência", "Wi-fi gratuito"], "explicacao": "Lei 7.405/1985."}, {"id": 10737, "materia": "pcd", "nivel": 1, "enunciado": "Pelo Estatuto da PcD, o ambiente que pode ser usado por todos, com segurança e autonomia, atende ao conceito de:", "opcoes": ["Acessibilidade", "Tutela", "Curatela", "Interdição"], "explicacao": "Art. 3º, I, da Lei 13.146/2015."}, {"id": 10738, "materia": "pcd", "nivel": 1, "enunciado": "Praticar discriminação contra pessoa por causa de sua deficiência, pelo Estatuto da PcD, é:", "opcoes": ["Crime, com pena de reclusão", "Apenas falta ética", "Contravenção penal", "Ilícito apenas civil, sem consequência penal"], "explicacao": "Art. 88 da Lei 13.146/2015: reclusão de 1 a 3 anos e multa."}, {"id": 10739, "materia": "ia", "nivel": 0, "enunciado": "O comando ou pergunta que o usuário digita para uma IA gerar a resposta chama-se:", "opcoes": ["Prompt", "Pixel", "Driver", "Plug-in"], "explicacao": "Prompt é a instrução dada à IA."}, {"id": 10740, "materia": "ia", "nivel": 0, "enunciado": "O ChatGPT e o Claude são exemplos de:", "opcoes": ["Modelos de linguagem de inteligência artificial", "Programas antivírus de computador e celular", "Sistemas operacionais", "Redes sociais"], "explicacao": "Geram texto a partir de comandos."}, {"id": 10741, "materia": "ia", "nivel": 1, "enunciado": "Ensinar um sistema a reconhecer padrões a partir de muitos exemplos chama-se:", "opcoes": ["Aprendizado de máquina", "Formatação de disco", "Compressão de arquivos", "Backup incremental"], "explicacao": "Machine learning."}, {"id": 10742, "materia": "ia", "nivel": 1, "enunciado": "Uma boa prática ao usar IA nos estudos é:", "opcoes": ["Conferir as respostas em fontes confiáveis", "Aceitar tudo o que a IA responder, sem conferir", "Compartilhar suas senhas com a IA", "Nunca mais ler a lei seca"], "explicacao": "A IA pode errar (\"alucinar\")."}, {"id": 10743, "materia": "sust", "nivel": 0, "enunciado": "Separar o lixo reciclável do orgânico é chamado de:", "opcoes": ["Coleta seletiva", "Compostagem industrial", "Aterro sanitário", "Incineração"], "explicacao": "Facilita a reciclagem."}, {"id": 10744, "materia": "sust", "nivel": 0, "enunciado": "A fonte de energia que vem do sol é a energia:", "opcoes": ["Solar", "Eólica", "Nuclear", "Térmica a carvão"], "explicacao": "Eólica vem do vento."}, {"id": 10745, "materia": "sust", "nivel": 1, "enunciado": "Os 3 Rs da sustentabilidade são reduzir, reutilizar e:", "opcoes": ["Reciclar", "Reformar", "Recolher", "Repetir"], "explicacao": "Reduzir, Reutilizar e Reciclar."}, {"id": 10746, "materia": "sust", "nivel": 1, "enunciado": "A lei que trata dos crimes ambientais é a Lei:", "opcoes": ["9.605/1998", "12.305/2010", "6.938/1981", "11.445/2007"], "explicacao": "Lei de Crimes Ambientais."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 10547 and 10746 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
